{"workdir": "/home/zhouhuijuan1987/wiki/youtube-video-research-wiki", "command": "python3 << 'EOF'
import os
import re

wiki_local_path = "/home/zhouhuijuan1987/wiki/youtube-video-research-wiki"
youtube_links_dir = os.path.join(wiki_local_path, "raw", "youtube-links")
youtube_urls = set()

if os.path.exists(youtube_links_dir):
    for filename in os.listdir(youtube_links_dir):
        if filename.endswith(".md") and filename != ".gitkeep":
            filepath = os.path.join(youtube_links_dir, filename)
            try:
                with open(filepath, 'r', encoding='utf-8') as f:
                    content = f.read()
                    # Regex to capture all specified YouTube URL formats
                    urls = re.findall(r'https?://(?:www\.)?(?:youtube\.com/watch\?v=|youtu\.be/)[\w\-?=&]+', content)
                    for url in urls:
                        youtube_urls.add(url.strip())
            except Exception as e:
                print(f"Error reading or processing file {filepath}: {e}", file=os.stderr)
else:
    print(f"Directory not found: {youtube_links_dir}", file=os.stderr)

if youtube_urls:
    print(" ".join(sorted(list(youtube_urls))))
else:
    print("NO_URLS_FOUND")
EOF"}

